package com.careerpilot.modules.jobmatch.service;
import com.careerpilot.config.JobMatchProperties;import com.careerpilot.exception.NotFoundException;import com.careerpilot.modules.auth.entity.User;import com.careerpilot.modules.jobmatch.dto.*;import com.careerpilot.modules.jobmatch.entity.*;import com.careerpilot.modules.jobmatch.mapper.JobMatchMapper;import com.careerpilot.modules.jobmatch.repository.JobMatchRepository;import com.careerpilot.modules.jobmatch.scoring.JobMatchScoringService;import com.careerpilot.modules.profile.repository.*;import com.careerpilot.modules.resume.entity.ParseStatus;import com.careerpilot.modules.resume.exception.ResumeException;import com.careerpilot.modules.resume.repository.ResumeRepository;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class JobMatchService{private final JobMatchRepository matches;private final ResumeRepository resumes;private final ProfileRepository profiles;private final UserSkillRepository userSkills;private final JobMatchScoringService scoring;private final JobMatchMapper mapper;private final JobMatchProperties properties;public JobMatchService(JobMatchRepository matches,ResumeRepository resumes,ProfileRepository profiles,UserSkillRepository userSkills,JobMatchScoringService scoring,JobMatchMapper mapper,JobMatchProperties properties){this.matches=matches;this.resumes=resumes;this.profiles=profiles;this.userSkills=userSkills;this.scoring=scoring;this.mapper=mapper;this.properties=properties;}
 @Transactional public JobMatchResponse create(User user,CreateJobMatchRequest request){var resume=resumes.findByIdAndUserId(request.resumeId(),user.getId()).orElseThrow(()->new NotFoundException("Resume not found"));if(resume.getParseStatus()!=ParseStatus.PARSED)throw new ResumeException(HttpStatus.CONFLICT,"Resume must be successfully parsed before matching");String jd=request.jobDescription().strip();if(jd.length()<properties.minDescriptionCharacters())throw new ResumeException(HttpStatus.BAD_REQUEST,"Job description is too short");if(jd.length()>properties.maxDescriptionCharacters())throw new ResumeException(HttpStatus.PAYLOAD_TOO_LARGE,"Job description exceeds the configured limit");var score=scoring.score(jd,resume,profiles.findByUserId(user.getId()).orElse(null),userSkills.findByUserIdOrderBySkillDisplayName(user.getId()));JobMatch match=new JobMatch();match.setUser(user);match.setResume(resume);match.setJobTitle(request.jobTitle().strip());match.setCompanyName(blank(request.companyName()));match.setJobDescription(jd);match.setOverallMatchScore(score.overall());match.setKeywordMatchScore(score.keyword());match.setSkillMatchScore(score.skill());match.setSemanticMatchScore(score.semantic());match.setSemanticStatus(score.semanticStatus());match.setExperienceMatchScore(score.experience().score());match.setExperienceStatus(score.experience().status());match.setEducationMatchScore(score.education().score());match.setEducationStatus(score.education().status());match.setScoringVersion(properties.scoringVersion());for(var value:score.skills()){JobMatchSkill skill=new JobMatchSkill();skill.setJobMatch(match);skill.setSkillName(value.display());skill.setNormalizedSkillName(value.normalized());skill.setMatchStatus(value.status());skill.setImportance(value.importance());skill.setPriority(value.priority());skill.setSource(value.source());skill.setEvidence(value.evidence());skill.setRecommendation(value.recommendation());match.getSkills().add(skill);}return mapper.detail(matches.save(match));}
 @Transactional(readOnly=true)public List<JobMatchSummaryResponse>history(User user){return matches.findByUserIdOrderByCreatedAtDesc(user.getId()).stream().map(mapper::summary).toList();}@Transactional(readOnly=true)public JobMatchResponse get(User user,UUID id){return mapper.detail(matches.findByIdAndUserId(id,user.getId()).orElseThrow(()->new NotFoundException("Job match not found")));}@Transactional(readOnly=true)public JobMatchSummaryResponse latest(User user){return matches.findFirstByUserIdOrderByCreatedAtDesc(user.getId()).map(mapper::summary).orElse(null);}private String blank(String value){return value==null||value.isBlank()?null:value.strip();}}
